create extension if not exists "uuid-ossp" with schema extensions;
create type public.app_role as enum ('student','tpo','admin');
create type public.application_status as enum ('Applied','Under Review','Shortlisted','Interview','Selected','Not Shortlisted','Rejected');
create type public.project_status as enum ('Submitted','Under Review','Rework Required','Verified');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, email text, role public.app_role not null default 'student', department text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.student_profiles (id uuid primary key default uuid_generate_v4(), user_id uuid unique not null references public.profiles(id) on delete cascade, student_id text unique, branch text, semester int check (semester between 1 and 12), cgpa numeric(4,2) check (cgpa between 0 and 10), backlogs int not null default 0, tenth_percentage numeric(5,2), twelfth_percentage numeric(5,2), career_intent text, onboarding_complete boolean not null default false);
create table public.skills (id uuid primary key default uuid_generate_v4(), name text unique not null, category text, market_demand numeric(5,2) default 0, demand_trend text default 'steady');
create table public.student_skills (student_id uuid references public.student_profiles(id) on delete cascade, skill_id uuid references public.skills(id) on delete cascade, proficiency numeric(5,2) check (proficiency between 0 and 100), source text default 'self_reported', verified boolean default false, primary key(student_id,skill_id));
create table public.projects (id uuid primary key default uuid_generate_v4(), student_id uuid references public.student_profiles(id) on delete cascade, title text not null, description text, github_url text, live_demo_url text, status public.project_status not null default 'Submitted', feedback text, created_at timestamptz default now());
create table public.roles (id uuid primary key default uuid_generate_v4(), name text unique not null, description text, market_demand text);
create table public.role_skills (role_id uuid references public.roles(id) on delete cascade, skill_id uuid references public.skills(id) on delete cascade, required_level numeric(5,2), is_preferred boolean default false, primary key(role_id,skill_id));
create table public.companies (id uuid primary key default uuid_generate_v4(), name text not null, website text);
create table public.jobs (id uuid primary key default uuid_generate_v4(), company_id uuid references public.companies(id), role_id uuid references public.roles(id), title text not null, description text, ctc text, location text, minimum_cgpa numeric(4,2) default 0, allowed_branches text[] default '{}', max_backlogs int default 0, graduation_year int, deadline date, external_application_url text, is_demo boolean default false, created_at timestamptz default now());
create table public.job_requirements (job_id uuid references public.jobs(id) on delete cascade, skill_id uuid references public.skills(id), required_level numeric(5,2), is_preferred boolean default false, primary key(job_id,skill_id));
create table public.applications (id uuid primary key default uuid_generate_v4(), job_id uuid references public.jobs(id), student_id uuid references public.student_profiles(id), status public.application_status not null default 'Applied', match_score numeric(5,2), eligibility boolean, applied_at timestamptz default now(), unique(job_id,student_id));
create table public.application_status_history (id uuid primary key default uuid_generate_v4(), application_id uuid references public.applications(id) on delete cascade, status public.application_status not null, changed_by uuid references public.profiles(id), created_at timestamptz default now());
create table public.notifications (id uuid primary key default uuid_generate_v4(), user_id uuid references public.profiles(id) on delete cascade, title text not null, body text not null, type text, read_at timestamptz, created_at timestamptz default now());
create table public.courses (id uuid primary key default uuid_generate_v4(), title text not null, description text, skill_id uuid references public.skills(id), difficulty text, estimated_hours int, is_demo boolean default true);
create table public.course_phases (id uuid primary key default uuid_generate_v4(), course_id uuid references public.courses(id) on delete cascade, title text not null, description text, phase_order int not null);
create table public.learning_resources (id uuid primary key default uuid_generate_v4(), phase_id uuid references public.course_phases(id) on delete cascade, title text not null, url text not null, resource_type text, estimated_minutes int);
create table public.assessments (id uuid primary key default uuid_generate_v4(), course_id uuid references public.courses(id) on delete cascade, title text not null);
create table public.assessment_questions (id uuid primary key default uuid_generate_v4(), assessment_id uuid references public.assessments(id) on delete cascade, question text not null, options jsonb not null, correct_answer text not null, explanation text, difficulty text, skill_id uuid references public.skills(id));
create table public.student_course_progress (student_id uuid references public.student_profiles(id) on delete cascade, course_id uuid references public.courses(id), progress numeric(5,2) default 0, primary key(student_id,course_id));
create table public.student_assessment_attempts (id uuid primary key default uuid_generate_v4(), student_id uuid references public.student_profiles(id), assessment_id uuid references public.assessments(id), score numeric(5,2), attempted_at timestamptz default now());
create table public.skill_verifications (id uuid primary key default uuid_generate_v4(), student_id uuid references public.student_profiles(id), skill_id uuid references public.skills(id), project_id uuid references public.projects(id), verified_by uuid references public.profiles(id), level numeric(5,2), created_at timestamptz default now());
create table public.market_snapshots (id uuid primary key default uuid_generate_v4(), source text not null, captured_at timestamptz default now(), is_fallback boolean default false, metadata jsonb default '{}');
create table public.bootcamps (id uuid primary key default uuid_generate_v4(), title text not null, description text, target_skill_id uuid references public.skills(id), source text, created_by uuid references public.profiles(id), created_at timestamptz default now());
create table public.student_polls (id uuid primary key default uuid_generate_v4(), question text not null, created_by uuid references public.profiles(id), active boolean default true);
create table public.poll_options (id uuid primary key default uuid_generate_v4(), poll_id uuid references public.student_polls(id) on delete cascade, label text not null);
create table public.poll_responses (poll_id uuid references public.student_polls(id) on delete cascade, option_id uuid references public.poll_options(id), student_id uuid references public.student_profiles(id) on delete cascade, primary key(poll_id,student_id));
create index applications_student_idx on public.applications(student_id); create index jobs_deadline_idx on public.jobs(deadline); create index notifications_user_idx on public.notifications(user_id,created_at desc);

alter table public.profiles enable row level security; alter table public.student_profiles enable row level security; alter table public.student_skills enable row level security; alter table public.projects enable row level security; alter table public.applications enable row level security; alter table public.notifications enable row level security;
create or replace function public.is_tpo() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role in ('tpo','admin')); $$;
create policy profiles_self on public.profiles for select using(id=auth.uid()); create policy profiles_tpo on public.profiles for select using(public.is_tpo());
create policy student_self on public.student_profiles for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy student_tpo on public.student_profiles for select using(public.is_tpo());
create policy skills_self on public.student_skills for all using(student_id in(select id from student_profiles where user_id=auth.uid())) with check(student_id in(select id from student_profiles where user_id=auth.uid()));
create policy projects_self on public.projects for all using(student_id in(select id from student_profiles where user_id=auth.uid())) with check(student_id in(select id from student_profiles where user_id=auth.uid())); create policy projects_tpo on public.projects for select using(public.is_tpo()); create policy projects_tpo_update on public.projects for update using(public.is_tpo());
create policy applications_self on public.applications for select using(student_id in(select id from student_profiles where user_id=auth.uid())); create policy applications_insert on public.applications for insert with check(student_id in(select id from student_profiles where user_id=auth.uid())); create policy applications_tpo on public.applications for all using(public.is_tpo());
create policy notifications_self on public.notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid());
